const t2 = 0;
const fired2: number[] = [];
let fn2: () => void = throttle(
  () => fired2.push(t2++),
  1,
  50
);
fn2();
fn2(); // skipped
fn2(); // skipped (window not reset)
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
fn2(); // still skipped
assert(fired2.length === 1, `exactly 1 fire per 1-per-window (got ${fired2.length})`);

if (failures > 0) {
